CREATE: base => Record { Nom = Ada, Role = Lecteur, Actif = Oui }
WITH: admin => Record { Nom = Ada, Role = Admin, Actif = Oui }
WITH: copie => Record { Nom = Ada, Role = Lecteur, Actif = Oui }
EQUALS: base == admin => False
EQUALS: base == copie => True (Egalite structurelle)
EQUALS: admin == admin => True
CREATE: inverse => Record { Actif = Oui, Role = Lecteur, Nom = Ada }
EQUALS: inverse == base => True (Egalite structurelle)

CREATE: src => Record { A = 1, B = 2 }
WITH: copie => Record { A = 1, B = 2 }
WITH: finale => Record { A = 1, B = 5 }
EQUALS: src == copie => True (Egalite structurelle)
EQUALS: src == finale => False
EQUALS: finale == finale => True
